/** Markdown files imported as text (`with { type: "text" }`), embedded in the compiled binary. */
declare module "*.md" {
  const text: string;
  export default text;
}

/** Files imported with `{ type: "file" }`: their path (in the compiled binary, a /$bunfs/ path). */
declare module "*.tar.gz" {
  const path: string;
  export default path;
}

/** Sources tarball as base64, generated by scripts/build.sh (absent until a build: this keeps tsc happy). */
declare module "#payload" {
  const base64: string;
  export default base64;
}
